Lemma geo_0RB1LC_1LA1RB_0RD0LA_1RB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LA1RB_0RD0LA_1RB1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LC_1LA1RB_0RD0LA_1RB1RD
             = (StB, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
