(** Its mirror 0LB1RC_1RA1LB_0LD1RD_0RA0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LC_1LA1RB_0RD1LD_0LA0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1LA1RB_0RD1LD_0LA0LA : list Instr := [].
Definition tmw_0RB1LC_1LA1RB_0RD1LD_0LA0LA : TM := tm_wrap_trs tmm_0RB1LC_1LA1RB_0RD1LD_0LA0LA pins_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
Local Notation tm := tmw_0RB1LC_1LA1RB_0RD1LD_0LA0LA.

Lemma mirror_ok_0RB1LC_1LA1RB_0RD1LD_0LA0LA : mirror_tm tm_0RB1LC_1LA1RB_0RD1LD_0LA0LA = tmm_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA (p : positive) : cconf := (StA, (Ap_Alph_011_111_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA.

(** ** The certificate *)

