Definition Z0_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StA (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StA (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB1LC_1LA1RB_0RD1LD_0LA0LA : list lstep := [SWin 2].

Lemma run_z_0RB1LC_1LA1RB_0RD1LD_0LA0LA : srun tm false true chz_0RB1LC_1LA1RB_0RD1LD_0LA0LA Z0_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Some (Z1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, 0, 2).
