Lemma run_p_0RB1LC_1LA1RB_0RD1LD_0LA0LA : srun tm false true chp_0RB1LC_1LA1RB_0RD1LD_0LA0LA P0_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Some (P1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StA (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_101_111_1 at StC *)
Definition Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA (v : positive) : cconf := (StC, (Ap_Alph_101_111_1 v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall n, Ap_Alph_101_111_1 (pow2 n) = rep [S1;S0;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB1LC_1LA1RB_0RD1LD_0LA0LA : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_0RB1LC_1LA1RB_0RD1LD_0LA0LA : srun tm false true chn_0RB1LC_1LA1RB_0RD1LD_0LA0LA AI0_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Some (AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, 6, 8).
