(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_1LA1RB_0RD1LD_0LA0LA : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LC_1LA1RB_0RD1LD_0LA0LA : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SWinR 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1LC_1LA1RB_0RD1LD_0LA0LA : srun tm true true che_0RB1LC_1LA1RB_0RD1LD_0LA0LA BE0_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Some (B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, 6, 11).
