(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LC_1LA1RB_0RD1LD_0LA0LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, Z0_0RB1LC_1LA1RB_0RD1LD_0LA0LA, Z1_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LC_1LA1RB_0RD1LD_0LA0LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LC_1LA1RB_0RD1LD_0LA0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, P0_0RB1LC_1LA1RB_0RD1LD_0LA0LA, P1_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LC_1LA1RB_0RD1LD_0LA0LA p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LC_1LA1RB_0RD1LD_0LA0LA Z0_0RB1LC_1LA1RB_0RD1LD_0LA0LA Z1_0RB1LC_1LA1RB_0RD1LD_0LA0LA 0 2
               run_z_0RB1LC_1LA1RB_0RD1LD_0LA0LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LC_1LA1RB_0RD1LD_0LA0LA P0_0RB1LC_1LA1RB_0RD1LD_0LA0LA P1_0RB1LC_1LA1RB_0RD1LD_0LA0LA 6 8
               run_p_0RB1LC_1LA1RB_0RD1LD_0LA0LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, B0_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA
             = (StA, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LC_1LA1RB_0RD1LD_0LA0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LC_1LA1RB_0RD1LD_0LA0LA. reflexivity.
Qed.

Lemma gsn_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, AI0_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 8), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0RD1LD_0LA0LA v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0RD1LD_0LA0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0RD1LD_0LA0LA AI0_0RB1LC_1LA1RB_0RD1LD_0LA0LA AI1_0RB1LC_1LA1RB_0RD1LD_0LA0LA 6 8
           run_inner_0RB1LC_1LA1RB_0RD1LD_0LA0LA (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall j, lift (cden [] [] j BB1_0RB1LC_1LA1RB_0RD1LD_0LA0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LC_1LA1RB_0RD1LD_0LA0LA = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB1LC_1LA1RB_0RD1LD_0LA0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA. rewrite epow2_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LC_1LA1RB_0RD1LD_0LA0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LC_1LA1RB_0RD1LD_0LA0LA.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0RD1LD_0LA0LA, cden, BE0_0RB1LC_1LA1RB_0RD1LD_0LA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0RD1LD_0LA0LA p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RD1LD_0LA0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0RD1LD_0LA0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0RD1LD_0LA0LA B0_0RB1LC_1LA1RB_0RD1LD_0LA0LA BB1_0RB1LC_1LA1RB_0RD1LD_0LA0LA 6 4
             run_boot_0RB1LC_1LA1RB_0RD1LD_0LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 11), (cden [] [] j B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA).
    split; [| exact (geo_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0RD1LD_0LA0LA j).
    exact (srun_sound tm true true che_0RB1LC_1LA1RB_0RD1LD_0LA0LA BE0_0RB1LC_1LA1RB_0RD1LD_0LA0LA B1_0RB1LC_1LA1RB_0RD1LD_0LA0LA 6 11
             run_exit_0RB1LC_1LA1RB_0RD1LD_0LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_0RD1LD_0LA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_0RD1LD_0LA0LA p j' E).
