Lemma fire_0RB1LC_1LA1RB_0RD1LD_0RB0LA : forall t, ~ In t pins_0RB1LC_1LA1RB_0RD1LD_0RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
