Lemma lapil_0RB1LC_1LA1RB_0RD1LD_1LC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0RD1LD_1LC0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0RD1LD_1LC0LA p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RD1LD_1LC0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0RD1LD_1LC0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0RD1LD_1LC0LA B0_0RB1LC_1LA1RB_0RD1LD_1LC0LA BB1_0RB1LC_1LA1RB_0RD1LD_1LC0LA 6 4
             run_boot_0RB1LC_1LA1RB_0RD1LD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_0RB1LC_1LA1RB_0RD1LD_1LC0LA).
    split; [| exact (geo_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0RD1LD_1LC0LA j).
    exact (srun_sound tm true true che_0RB1LC_1LA1RB_0RD1LD_1LC0LA BE0_0RB1LC_1LA1RB_0RD1LD_1LC0LA B1_0RB1LC_1LA1RB_0RD1LD_1LC0LA 6 13
             run_exit_0RB1LC_1LA1RB_0RD1LD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_0RD1LD_1LC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LA1RB_0RD1LD_1LC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

