  apply (fire_of_run_instr tm Cc true true l B0_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LC_1LA1RB_0RD1LD_1LC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LC_1LA1RB_0RD1LD_1LC0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LC_1LA1RB_0RD1LD_1LC0LA t p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RD1LD_1LC0LA). split;
      [| exact (gbo_0RB1LC_1LA1RB_0RD1LD_1LC0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0RD1LD_1LC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0RD1LD_1LC0LA B0_0RB1LC_1LA1RB_0RD1LD_1LC0LA BB1_0RB1LC_1LA1RB_0RD1LD_1LC0LA 6 4
             run_boot_0RB1LC_1LA1RB_0RD1LD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LC_1LA1RB_0RD1LD_1LC0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LC_1LA1RB_0RD1LD_1LC0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LC_1LA1RB_0RD1LD_1LC0LA : forall t, ~ In t pins_0RB1LC_1LA1RB_0RD1LD_1LC0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1LC_1LA1RB_0RD1LD_1LC0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LC_1LA1RB_0RD1LD_1LC0LA (StC, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LC_1LA1RB_0RD1LD_1LC0LA [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LC_1LA1RB_0RD1LD_1LC0LA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LC_1LA1RB_0RD1LD_1LC0LA [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1LC_1LA1RB_0RD1LD_1LC0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

