Lemma gz_0RB1LC_1LA1RB_0RD1LD_1RD0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LC_1LA1RB_0RD1LD_1RD0LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LC_1LA1RB_0RD1LD_1RD0LA = Cc (Pos.succ p).
