Lemma lapi_0RB1LC_1LA1RB_0RD1LD_1RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
