(** 0RB1LC_1LA1RB_1LD1LD_0LA0RC *)
(** 0RB1LC_1LA1RB_1LD1LD_0LA0RC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LC_1LA1RB_1LD1LD_0LA0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StC end.

(** Its mirror 0LB1RC_1RA1LB_1RD1RD_0RA0LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LC_1LA1RB_1LD1LD_0LA0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1LA1RB_1LD1LD_0LA0RC : list Instr := [].
Definition tmw_0RB1LC_1LA1RB_1LD1LD_0LA0RC : TM := tm_wrap_trs tmm_0RB1LC_1LA1RB_1LD1LD_0LA0RC pins_0RB1LC_1LA1RB_1LD1LD_0LA0RC.
