    rewrite (gso_0RB1LC_1LA1RB_1LD1LD_0RB0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_1LD1LD_0RB0LA B0_0RB1LC_1LA1RB_1LD1LD_0RB0LA BB1_0RB1LC_1LA1RB_1LD1LD_0RB0LA 6 5
