  - destruct (lapi_0RB1LC_1LA1RB_1RB1LD_0RA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LC_1LA1RB_1RB1LD_0RA0LA B0_0RB1LC_1LA1RB_1RB1LD_0RA0LA B1_0RB1LC_1LA1RB_1RB1LD_0RA0LA 6 22 p j' [] []).
    + exact run_ovf_0RB1LC_1LA1RB_1RB1LD_0RA0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LC_1LA1RB_1RB1LD_0RA0LA p j' E).
    + exact (geo_0RB1LC_1LA1RB_1RB1LD_0RA0LA p j' E).
    + lia.
