(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_1RB1LD_0RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
