    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_1RB1LD_0RB0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LA1RB_1RB1LD_0RB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
