Lemma gen_0RB1LC_1LA1RB_1RC1LD_0RB0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1LC_1LA1RB_1RC1LD_0RB0LA) = lift (Cin (Pos.succ v)).
