(** ** Bootstrap *)

Lemma boot_0RB1LC_1LA1RB_1RC1LD_0RD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 10.
  assert (H : match csteps tm 10 c0 with
